WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT id, session_id, event_type, page, event_time, duration_sec, session_id_2 FROM sessions_web_events ORDER BY event_type NULLS LAST
